import * as THREE from 'three/webgpu';
import { NodeMaterial, vec3, mix, uv, positionLocal, mul, add, normalize, length, pow } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // Root group for the hero element
  const root = new THREE.Group();
  root.position.set(...config.position ?? [0, 0, 0]);
  root.rotation.set(...config.rotation ?? [0, 0, 0]);
  root.scale.set(...config.scale ?? [1, 1, 1]);

  // ---------- WATCH MESH ----------
  // Load GLB (synchronous via cached loader)
  const gltf = ctx.glbLoader(config.assets?.meshUrl);
  const watchGroup = gltf.scene || gltf; // GLTF may return Object3D directly
  // Ensure watch is centered and scaled (spec says already normalized)
  root.add(watchGroup);

  // ---------- PLINTH ----------
  const plinthRadius = 1.4;
  const plinthHeight = 0.25;
  const plinthGeom = new THREE.CylinderGeometry(plinthRadius, plinthRadius, plinthHeight, 32);
  const plinthMat = new THREE.MeshStandardMaterial({
    color: 0x14141a,
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinthMesh = new THREE.Mesh(plinthGeom, plinthMat);
  // Position so top face is at y = -1.1
  plinthMesh.position.y = -1.1 - plinthHeight / 2;
  root.add(plinthMesh);

  // ---------- BACKDROP PLANE WITH VERTICAL GRADIENT ----------
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const gradientMaterial = new NodeMaterial();
  // Create a simple vertical gradient based on local Y (0 bottom to 1 top)
  const gradient = mix(
    vec3(0x0b / 255, 0x0b / 255, 0x10 / 255), // #0b0b10
    vec3(0x16 / 255, 0x16 / 255, 0x1d / 255), // #16161d
    uv().y
  );
  gradientMaterial.color = gradient;
  gradientMaterial.transparent = true;
  gradientMaterial.depthWrite = false;
  const backdropMesh = new THREE.Mesh(backdropGeom, gradientMaterial);
  backdropMesh.position.set(0, 0, -2.5);
  root.add(backdropMesh);

  // ---------- CONTACT SHADOW ----------
  const shadowGeom = new THREE.CircleGeometry(1.6, 64);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.55,
    depthWrite: false,
  });
  const shadowMesh = new THREE.Mesh(shadowGeom, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  // Place just under the plinth
  shadowMesh.position.y = plinthMesh.position.y - plinthHeight / 2 - 0.001;
  root.add(shadowMesh);

  // ---------- ACCENT RIM LIGHT ----------
  // Simple directional light that grazes left side
  const rimLight = new THREE.DirectionalLight(0xff2a38, 1.6);
  rimLight.position.set(-2, 1, 2);
  rimLight.target = watchGroup;
  root.add(rimLight);
  root.add(rimLight.target);

  // ---------- TEXT ----------
  const textGroup = new THREE.Group();

  // Helper to create MSDF text mesh
  function createText(content, style, yOffset) {
    const { fontSize, fontWeight, family, letterSpacing, lineHeight } = style;
    const textMesh = ctx.fontAtlas.createTextMesh({
      text: content,
      fontSize,
      fontWeight,
      fontFamily: family,
      letterSpacing,
      lineHeight,
      color: 0xe8ecf2, // paper color for readability
      atlasIndex: config.atlasRegion?.atlas ?? 0,
      sourceRect: config.atlasRegion?.sourceRect,
    });
    textMesh.position.set(0, yOffset, 0);
    return textMesh;
  }

  const headlineStyle = {
    fontSize: 68,
    fontWeight: 600,
    family: 'Lora',
    letterSpacing: -0.005,
    lineHeight: 1.1,
  };
  const bodyStyle = {
    fontSize: 26,
    fontWeight: 400,
    family: 'JetBrains Mono',
    letterSpacing: 0,
    lineHeight: 1.5,
  };
  const captionStyle = {
    fontSize: 18,
    fontWeight: 400,
    family: 'JetBrains Mono',
    letterSpacing: 0.08,
    lineHeight: 1.4,
  };

  const headlineY = -1.5;
  const bodyY = -1.5 - (headlineStyle.fontSize / 100) * 0.5; // approximate spacing
  const captionY = headlineY - 0.5;

  if (config.textContent?.headline) {
    textGroup.add(createText(config.textContent.headline, headlineStyle, headlineY));
  }
  if (config.textContent?.body) {
    textGroup.add(createText(config.textContent.body, bodyStyle, bodyY));
  }
  if (config.textContent?.caption) {
    textGroup.add(createText(config.textContent.caption, captionStyle, captionY));
  }

  root.add(textGroup);

  // ---------- CINEMATIC PRIMITIVES ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const apply = ctx.primitives[prim.name];
      if (typeof apply === 'function') {
        apply(root, prim.params ?? {});
      }
    }
  }

  // ---------- USER DATA ----------
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometries, materials, textures
    plinthGeom.dispose();
    plinthMat.dispose();

    shadowGeom.dispose();
    shadowMat.dispose();

    backdropGeom.dispose();
    gradientMaterial.dispose();

    // Dispose GLTF resources
    if (watchGroup.traverse) {
      watchGroup.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose());
            } else {
              obj.material.dispose();
            }
          }
        }
      });
    }

    // Dispose text meshes
    textGroup.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      }
    });

    // Kill any GSAP timelines that may have been created (none directly here)
    gsap.globalTimeline.clear();

    // Remove from parent if attached
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
